WITH remaining_keys AS (SELECT order_id, product_id FROM order_items INTERSECT SELECT order_id, product_id FROM order_items WHERE order_id IN (8, 9, 18, 21)), kept_rows AS (SELECT s.* FROM order_items s INNER JOIN remaining_keys k ON s.order_id = k.order_id AND s.product_id = k.product_id) SELECT CASE WHEN quantity >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, APPROX_PERCENTILE(unit_price, 0.9) AS unit_price_p90, PERCENTILE_APPROX(quantity, 0.5) AS quantity_p50, BIT_OR(quantity) AS quantity_bit_or, COUNT(*) AS num_rows, PERCENTILE_APPROX(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles FROM kept_rows GROUP BY CASE WHEN quantity >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING quantity_p50 > 0 ORDER BY num_rows NULLS LAST;
